using Microsoft.Xna.Framework;
namespace StarlightSyndicateDemo;
public sealed class EncounterProfileO
{
 public string Id{get;set;}="";public string Name{get;set;}="";public string Family{get;set;}="Resident";public int Class{get;set;}=1;public int Pockets{get;set;}=1;public int Waves{get;set;}=3;public int Groups{get;set;}=3;public int MaxSize{get;set;}=6;public bool Capital{get;set;}
 public EncounterDefinitionF Definition=>new(Id,Name,Family=="Abyss"?"Abyss":"Sleeper","KillAll",Math.Clamp(Class,1,5),Pockets,Groups,"None",MaxSize,Family=="Abyss"?20:180,Family=="Resident"?"o_blue":Family=="Fabricator"?"o_fabricator_data":"o_bio",0,"Playable adaptation. Destroy each wave, collect physical loot and approach the unlocked gate. Exact source NPC rosters and reward tables remain unverified.");
}
public static class EncounterCatalogO
{
 public static readonly EncounterProfileO[] All=Enumerable.Range(1,6).SelectMany(c=>new[]{new EncounterProfileO{Id="o_resident_"+c,Class=c,Name="C"+c+" / "+new[]{"Perimeter camp","Perimeter checkpoint","Oruze construct","Frontier barracks","Core garrison","Core bastion"}[c-1],Groups=c+2},new EncounterProfileO{Id="o_data_"+c,Class=c,Name="C"+c+" / resident data archive",Pockets=2,Groups=c+2},new EncounterProfileO{Id="o_relic_"+c,Class=c,Name="C"+c+" / resident relic archive",Pockets=2,Groups=c+2},new EncounterProfileO{Id="o_fabricator_"+c,Class=c,Name="C"+c+" / rampant drone fabricator",Family="Fabricator",Waves=100,Groups=c+2}}).Concat(new[]{5,6}.Select(c=>new EncounterProfileO{Id="o_capital_"+c,Class=c,Name="C"+c+" / capital resident escalation",Capital=true,Groups=c+3})).ToArray();
 public static readonly string[] Pools=["Drone swarm","Drifter patrol","Triglavian squadron","Sleeper guardians","Imperial patrol","Pirate formation"];
 public static EncounterProfileO Abyss(int tier)=>new(){Id="abyss",Name="T"+tier+" / Abyss expedition",Family="Abyss",Class=tier+1,Pockets=3,Waves=1,Groups=2+tier,MaxSize=2};
}
public sealed partial class EncounterF
{
 public EncounterProfileO? ProfileO{get;set;}public int FilamentO{get;set;}public string TeamModeO{get;set;}="Cruiser";public List<string> CrewO{get;set;}=[];public string[] PoolsO{get;set;}=[];public float WeatherPenaltyO{get;set;}=.5f;public DateTime NextWaveO{get;set;}public int FabricatorDataO{get;set;}public DateTime DurationStartedO{get;set;}public float StabilityO{get;set;}=100;public int ThreatO{get;set;}public bool TerminalO{get;set;}
}
public sealed partial class DemoWorld
{
 public void EnsureResidentsO(){var source=SourceCatalogO.System(SystemId);if(source is not{Class:>=1 and <=6}||!Exploration.SeededSystems.Add(SystemId+"/residentsO"))return;foreach(var p in EncounterCatalogO.All.Where(p=>p.Class==source.Class))AddEncounterO(p,SystemId);}
 public EncounterF AddEncounterO(EncounterProfileO p,string system){var e=AddEncounterF(p.Id,system);e.ProfileO=new(){Id=p.Id,Name=p.Name,Family=p.Family,Class=p.Class,Pockets=p.Pockets,Waves=p.Waves,Groups=p.Groups,MaxSize=p.MaxSize,Capital=p.Capital};return e;}
 public bool EnterGuardO(EncounterF e)=>e.ProfileO?.Capital!=true||CombatHulls.Get(Player.CombatHull).Size>=4||Population.Pilots.Any(p=>p.Contracted&&!p.Suspended&&p.PaidThrough>Population.Tick&&p.System==SystemId&&p.Grid==Grid&&CombatHulls.Get(p.Fit.CombatHull).Size>=4);
 public bool SafeResidentHullO()=>ActiveEncounterF?.ProfileO is {Family:"Resident",Class:<=3}&&(Commander.Capsule||UnifiedCatalog40.Source(Player.CombatHull)?.Name=="Zephyr");
 public bool BindEncounterO(EncounterF e)
 {if(e.ProfileO is not{} p)return false;Player.WeatherPenaltyO=e.WeatherPenaltyO;SpawnWaveO(e);Targets.Add(new(){Id=$"f:{e.Id}:archive:{e.Pocket}",Name=p.Family=="Abyss"?"Biocombinative cache":"Research archive",Kind=TargetKind.Container,Hacked=true,Position=new(1500,0,0),Signature=100});Targets.Add(new(){Id=$"f:{e.Id}:gate:{e.Pocket}",Name=e.Pocket==p.Pockets-1?"Origin / completion gate":"Transfer conduit",Kind=TargetKind.Celestial,Position=new(12000,0,0),Signature=2000});
  if(p.Family=="Abyss"){Targets.Add(new(){Id=$"f:{e.Id}:cloud:{e.Pocket}",Name=e.Pocket%2==0?"Velocity cloud":"Signature cloud",Kind=TargetKind.Celestial,Position=new(6500,0,3000),Signature=3000});Targets.Add(new(){Id=$"f:{e.Id}:tower:{e.Pocket}",Name="Point defense tower",Kind=TargetKind.Celestial,Position=new(10000,0,-3000),Signature=2000});}
  if(p.Family=="Fabricator"){AddStructureO(e,"fabricator","Rampant drone fabricator",new(7500,0,0));foreach(string name in new[]{"Focuser","Prolonging","Rapid"})AddStructureO(e,"nanoswarm_"+name,name+" nanoswarm",new(9000,0,3000));}
  SyncEncounterF();return true;
 }
 void AddStructureO(EncounterF e,string key,string name,Vector3 pos){var t=MakeRaider(pos);t.Id=$"f:{e.Id}:{key}";t.Name=name;t.Profile!.SetStat("hp",1000);t.Profile.SetStat("shieldCapacity",1);t.Profile.SetStat("armorHP",1);t.Shield=t.Armor=0;t.Hull=1000;var n=new NpcStateL{Role="structure",Bounty=0};EnsureExplorationGraphL(e).Npcs[t.Id]=n;PrepareNpcL(t,n);Targets.Add(t);}
 public void SpawnWaveO(EncounterF e)
 {var p=e.ProfileO!;e.ThreatO=ThreatO();var run=EnsureExplorationGraphL(e);if(p.Family=="Fabricator"&&e.Wave==4&&e.DurationStartedO==default)e.DurationStartedO=Now;
  int count=Math.Min(14,p.Groups+(p.Capital?2:0)+(p.Family=="Fabricator"?e.ThreatO:0));for(int i=0;i<count;i++){string id=$"f:{e.Id}:oenemy:{e.Pocket}:{e.Wave}:{i}";if(run.Generated.Contains(id)||e.Events.Contains("kill:"+id))continue;var t=MakeRaider(new(3500+i*1400,0,i*500));t.Id=id;t.Name=(p.Family=="Abyss"?e.PoolsO.ElementAtOrDefault(e.Pocket)??"Abyss guard":p.Name)+" / wave "+(e.Wave+1)+" / "+i;var role=new NpcStateL{Role=i==1&&p.Class>1?"logistics":i==2?"ewar":"gunner",Ewar=i==2?(p.Family=="Fabricator"?"Damp":p.Class>=3?"Neutralizer":"Web"):"",Group=e.Pocket+"/"+e.Wave,Bounty=0};bool capital=i==0&&(p.Capital||p.Family=="Fabricator"&&e.ThreatO>=2&&e.Wave>=9);if(capital)t.Profile!.ApplyFleetHull(FleetCatalog.Source("Naglfar"),simulationOnly:true);else t.Profile!.SetCombatHull(p.Class>=4?"cruiser":t.Profile.CombatHull);float scale=1+p.Class*.5f+e.Wave*.08f+e.ThreatO*.3f;float hp=(capital?5000:p.Class>=4?300:50)*scale,defense=(capital?12000:p.Class>=4?700:100)*scale;t.Profile.SetStat("hp",hp);t.Profile.SetStat("shieldCapacity",defense);t.Profile.SetStat("armorHP",defense);t.Profile.EnvironmentF=p.Family=="Abyss"?e.Weather:"";t.Profile.WeatherPenaltyO=e.WeatherPenaltyO;run.Npcs[id]=role;PrepareNpcL(t,role);if(role.Role!="logistics"){var gun=WeaponCatalog.All.First(w=>w.Kind==WeaponKind.Turret&&w.Size==(capital?4:p.Class>=4?2:1));t.Profile.Weapons=[WeaponState.Create(gun.Id)];t.Profile.Weapons[0].Loaded=gun.Magazine;t.NpcAmmunition[t.Profile.Weapons[0].ChargeId]=gun.Magazine*8;}if(capital){t.Name="Infested capital drone / "+t.Name;var neut=EwarCatalog.All.First(x=>x.Kind==EwarKind.Neutralizer&&x.Size==4);t.Profile.Ewar=[EwarState.Create(neut.Id)];}t.Shield=t.Profile.MaxShield;t.Armor=t.Profile.MaxArmor;t.Hull=t.Profile.MaxHull;t.Cap=t.Profile.MaxCap;run.Generated.Add(id);Targets.Add(t);}
 }
 public bool EvaluateEncounterO(EncounterF e)
 {if(e.ProfileO is not{} p)return false;if(e.TerminalO){FinishLootO(e);return true;}bool clear=!Targets.Any(t=>t.Id.StartsWith($"f:{e.Id}:oenemy:{e.Pocket}:{e.Wave}:")&&t.Alive);
  if(p.Family=="Fabricator"){
   bool dead=Targets.FirstOrDefault(t=>t.Id==$"f:{e.Id}:fabricator")?.Alive==false;
   if(dead&&e.Events.Contains("waveclear:4")){e.TerminalO=true;FinishLootO(e);return true;}
   if(!clear||e.NextWaveO!=default)return true;
   if(e.Events.Add("waveclear:"+e.Wave)){e.FabricatorDataO+=(int)Math.Ceiling((1+e.Wave/5d)*(1+e.ThreatO)*(p.Class<=3?1.33:p.Class==4?1.25:1.2));e.Events.Add("wavesCompleted:"+(e.Wave+1));}
   if(e.Wave==99){e.TerminalO=true;FinishLootO(e);return true;}
   e.NextWaveO=Now.AddSeconds(e.Wave<4?6:new[]{18,15,12,6}[e.ThreatO]);SyncEncounterF();return true;
  }
  if(!clear)return true;if(e.Wave+1<p.Waves){e.Wave++;SpawnWaveO(e);SyncEncounterF();return true;}FinishLootO(e);return true;
 }
 void FinishLootO(EncounterF e)
 {var p=e.ProfileO!;if(e.Events.Add("loot:"+e.Pocket)){var cache=Targets.FirstOrDefault(t=>t.Id==$"f:{e.Id}:archive:{e.Pocket}");if(cache!=null){cache.Contents[p.Definition.Loot]=p.Family=="Fabricator"?e.FabricatorDataO:p.Family=="Abyss"?2+e.Tier:p.Class*3+(p.Capital?12:0);if(p.Family=="Abyss"){var f=SourceCatalogO.Data.Filaments.Single(f=>f.Tier==Math.Min(6,e.Tier+1)&&f.Weather==e.Weather);cache.Contents[f.Item]=1;if(EnsureExplorationGraphL(e).Roll()<.25)cache.Contents["e_mutator"]=1;}}}var graph=EnsureExplorationGraphL(e);graph.Pocket=e.Pocket;graph.Emit("objective/"+e.Pocket);graph.Pump(Now);e.PocketReady=graph.Fired.Contains("ready/"+e.Pocket);SyncEncounterF();}
 public int RampancyO(Ship ship){string cls=FleetCatalog.ById.TryGetValue(ship.CombatHull,out var hull)?hull.Class:CombatHulls.Get(ship.CombatHull).Role;return cls switch{"ForceAuxiliary" or "Force Auxiliary" or "ForceAux"=>36,"Marauder"=>12,"BlackOps" or "Black Ops"=>8,"CommandShip" or "Command Ship" or "Command"=>3,"Battlecruiser" or "Attack Battlecruiser" or "Combat Battlecruiser"=>2,"StrategicCruiser" or "Strategic Cruiser"=>4,"HeavyAssault" or "Heavy Assault Cruiser"=>2,"Logistics" or "Logistics Cruiser"=>2,"Cruiser" or "Force Recon Ship" or "Combat Recon Ship" or "Heavy Interdiction Cruiser" or "Flag Cruiser" or "ForceRecon" or "CombatRecon" or "HeavyInterdictor"=>1,"Battleship"=>6,_=>CombatHulls.Get(ship.CombatHull).Size>=4?72:ship.CombatHull=="battleship"?6:ship.CombatHull=="cruiser"?1:0};}
 public int ThreatO(){int points=RampancyO(Player)+Targets.Where(t=>t.Friendly&&t.Alive&&t.Profile!=null&&Vector3.Distance(t.Position,Player.Position)<100000).Sum(t=>RampancyO(t.Profile!));return points>=72?3:points>=36?2:points>=12?1:0;}
 public bool ProtectedTargetO(SpaceTarget t){var e=ActiveEncounterF;if(e?.ProfileO?.Family!="Fabricator")return false;if(t.Id==$"f:{e.Id}:fabricator")return !e.Events.Contains("waveclear:4");return t.Id.StartsWith($"f:{e.Id}:nanoswarm_")&&!new[]{5,10,15,25,35,45,65,85}.Contains(e.Wave+1);}
 public float FabricatorWeaponScaleO(SpaceTarget t,WeaponKind? kind)=>ActiveEncounterF?.ProfileO?.Family!="Fabricator"||!t.Id.StartsWith("f:"+ActiveEncounterF.Id+":")?1:kind switch{WeaponKind.Smartbomb=>0,WeaponKind.Arc=>.1f,WeaponKind.Bomb=>.05f,WeaponKind.DisruptiveLance=>.05f,_=>1};
 public void ApplyNanoswarmsO(EncounterF e){bool Alive(string s)=>Targets.Any(t=>t.Id==$"f:{e.Id}:nanoswarm_{s}"&&t.Alive);Player.NanoswarmRangeO=Alive("Focuser")?1.2f:1;Player.NanoswarmFlightO=Alive("Prolonging")?1.2f:1;Player.NanoswarmFighterO=Alive("Rapid")?1.2f:1;foreach(var t in Targets.Where(t=>t.Friendly&&t.Profile!=null)){t.Profile!.NanoswarmRangeO=Player.NanoswarmRangeO;t.Profile.NanoswarmFlightO=Player.NanoswarmFlightO;t.Profile.NanoswarmFighterO=Player.NanoswarmFighterO;}}
 public void ApplyCloudO(EncounterF e){var cloud=Targets.FirstOrDefault(t=>t.Id==$"f:{e.Id}:cloud:{e.Pocket}");string cloudKind=e.Pocket%2==0?"Velocity":"Signature";Player.CloudO=cloud!=null&&Vector3.Distance(Player.Position,cloud.Position)<3000?cloudKind:"";foreach(var t in Targets.Where(t=>t.Profile!=null))t.Profile!.CloudO=cloud!=null&&Vector3.Distance(t.Position,cloud.Position)<3000?cloudKind:"";}
 public void TickEncountersO(double seconds)
 {var e=ActiveEncounterF;if(e?.ProfileO is not{} p||e.State!="Active")return;
  if(p.Family=="Fabricator"){if(e.NextWaveO!=default&&Now>=e.NextWaveO){e.NextWaveO=default;e.Wave++;SpawnWaveO(e);}e.ThreatO=ThreatO();ApplyNanoswarmsO(e);if(e.Wave>=4&&seconds>0){bool present=Player.Position.Length()<100000||Targets.Any(t=>t.Friendly&&t.Alive&&t.Position.Length()<100000);e.StabilityO=Math.Clamp(e.StabilityO+(float)seconds*(present?.5f:-1),0,100);if(e.StabilityO<=0){FailEncounterF(e,"Fabricator stability exhausted");return;}}}
  if(p.Family=="Abyss"){ApplyCloudO(e);var tower=Targets.FirstOrDefault(t=>t.Id==$"f:{e.Id}:tower:{e.Pocket}");if(tower!=null){MissilesInFlight.RemoveAll(m=>Vector3.Distance(m.Position,tower.Position)<5000);foreach(var drone in Targets.Where(t=>t.DroneId.Length>0&&t.Alive&&Vector3.Distance(t.Position,tower.Position)<5000).ToArray())DealTargetDamage(drone,(float)(seconds*10),DamageType.EM);}}
  EvaluateEncounterO(e);
 }
 public static void ValidateStateO(ExplorationStateF state)
 {if(state.StockO.Values.Any(v=>v<0||v>5))throw new InvalidDataException("Invalid filament stock.");foreach(var e in state.Encounters.Where(e=>e.ProfileO!=null)){var p=e.ProfileO!;if(p.Id!=e.Template||p.Class<1||p.Class>7||p.Groups<1||p.Groups>14||p.Pockets<1||p.Pockets>3||p.Waves<1||p.Waves>100||e.Wave<0||e.Wave>99||!float.IsFinite(e.StabilityO)||e.StabilityO<0||e.StabilityO>100)throw new InvalidDataException("Invalid O encounter snapshot.");if(e.FilamentO>0&&(!SourceCatalogO.Data.Filaments.Any(f=>f.Id==e.FilamentO&&f.Tier==e.Tier&&f.Weather==e.Weather)||e.Template!="abyss"||e.PoolsO.Length!=3||e.PoolsO.Any(s=>!EncounterCatalogO.Pools.Contains(s))||e.CrewO.Count>2||e.CrewO.Distinct().Count()!=e.CrewO.Count||e.WeatherPenaltyO<.3||e.WeatherPenaltyO>.7))throw new InvalidDataException("Invalid Abyss admission snapshot.");}foreach(var h in state.Connections.Where(h=>h.SourceTypeO>0)){var t=SourceCatalogO.Data.Types.SingleOrDefault(t=>t.Id==h.SourceTypeO);if(t==null||!double.IsFinite(h.RemainingMass)||h.RemainingMass>h.InitialMassO||h.InitialMassO!=t.TotalMass||h.MaxShipMass!=t.JumpMass||SourceCatalogO.System(h.B) is not{} dest||!SourceCatalogO.Matches(t,dest))throw new InvalidDataException("Invalid source connection snapshot.");}}
}
